import SwiftUI

// 부위별 피로도를 사람 실루엣(전면/후면)에 색으로 표시.
// 진한 파랑 = 피로 높음(방금 운동), 연한 회색 = 회복됨.
// 세부부위 단위 색칠: 등(승모/광배/하부), 하체(대퇴/햄스트링/둔근/종아리)는 조각별로 칠해짐.
//
// 벡터 데이터: react-native-body-highlighter (MIT, https://github.com/HichamELBSI/react-native-body-highlighter)
// 의 남성 전/후면 근육맵 SVG 패스를 절대좌표 큐빅(M/L/C/Z)으로 변환해 내장. viewBox 724×1448.
// ⚠️ 앱 + 위젯 두 타겟에 포함 — Theme(앱 전용)을 참조하지 않는다.
struct BodyFatigueView: View {
    let levels: [MuscleRegion: Double]   // Fatigue.regionLevels() 결과
    var accent: Color = Color(red: 0.30, green: 0.65, blue: 0.91)   // 메인 블루(=Theme.or)
    var figureHeight: CGFloat = 180
    var spacing: CGFloat = 28
    var showLabels: Bool = true

    static let baseTone = Color(red: 0.894, green: 0.918, blue: 0.945)   // 미사용/회복 부위
    private static let subTone = Color(red: 0.61, green: 0.65, blue: 0.69)

    /// 피로도 → 색 히트 램프 (연하늘 → 메인 블루 → 진남색).
    /// 투명도만 조절하면 44% vs 100% 구분이 어려워, 색상 자체를 보간해 단계 차이를 또렷하게.
    static func heat(_ level: Double) -> Color {
        let l = max(0, min(1, level))
        let stops: [(t: Double, r: Double, g: Double, b: Double)] = [
            (0.0,  0.80, 0.90, 0.97),   // 살짝 자극 — 연하늘
            (0.35, 0.42, 0.72, 0.94),   // 낮음 — 하늘blue
            (0.65, 0.20, 0.55, 0.86),   // 보통 — 메인 블루
            (1.0,  0.03, 0.24, 0.52),   // 최대 피로 — 진남색
        ]
        for i in 0..<(stops.count - 1) where l <= stops[i + 1].t {
            let a = stops[i], b = stops[i + 1]
            let t = (l - a.t) / (b.t - a.t)
            return Color(red: a.r + (b.r - a.r) * t,
                         green: a.g + (b.g - a.g) * t,
                         blue: a.b + (b.b - a.b) * t)
        }
        return Color(red: 0.03, green: 0.24, blue: 0.52)
    }

    private func level(_ part: BodyPart?, _ sub: String?) -> Double {
        guard let part else { return 0 }
        if let v = levels[MuscleRegion(part: part, sub: sub)] { return v }
        return levels[MuscleRegion(part: part, sub: nil)] ?? 0   // 세부 없으면 부위 집계로
    }
    private func tint(_ part: BodyPart?, _ sub: String?) -> Color {
        let l = level(part, sub)
        guard l > 0.02 else { return Self.baseTone }
        return Self.heat(l)
    }

    var body: some View {
        HStack(spacing: spacing) {
            VStack(spacing: 3) {
                figure(BodyPaths.frontShapes, outline: BodyPaths.outlineFrontPath)
                if showLabels { Text("앞").font(.caption2).foregroundStyle(Self.subTone) }
            }
            VStack(spacing: 3) {
                figure(BodyPaths.backShapes, outline: BodyPaths.outlineBackPath)
                if showLabels { Text("뒤").font(.caption2).foregroundStyle(Self.subTone) }
            }
        }
        .frame(maxWidth: .infinity)
    }

    private func figure(_ shapes: [(part: BodyPart?, sub: String?, path: Path)], outline: Path) -> some View {
        Canvas { ctx, size in
            let s = min(size.width / 724, size.height / 1448)
            ctx.translateBy(x: (size.width - 724 * s) / 2, y: (size.height - 1448 * s) / 2)
            ctx.scaleBy(x: s, y: s)
            for (part, sub, path) in shapes {
                ctx.fill(path, with: .color(tint(part, sub)))
            }
            ctx.stroke(outline, with: .color(Color(red: 0.769, green: 0.824, blue: 0.875)), lineWidth: 2.5)
        }
        .frame(width: figureHeight * 724 / 1448, height: figureHeight)
    }
}

// MARK: - 인체 벡터 데이터 + 파서
private enum BodyPaths {
    /// 절대좌표 M/L/C/Z 전용 미니 파서 (오프라인에서 SVG 전 명령을 이 형식으로 변환해 둠)
    static func parse(_ d: String) -> Path {
        var p = Path()
        let t = d.split(separator: " ")
        var i = 0
        func n() -> CGFloat { defer { i += 1 }; return CGFloat(Double(t[i]) ?? 0) }
        while i < t.count {
            switch t[i] {
            case "M": i += 1; p.move(to: CGPoint(x: n(), y: n()))
            case "L": i += 1; p.addLine(to: CGPoint(x: n(), y: n()))
            case "C":
                i += 1
                let c1 = CGPoint(x: n(), y: n()), c2 = CGPoint(x: n(), y: n())
                p.addCurve(to: CGPoint(x: n(), y: n()), control1: c1, control2: c2)
            case "Z": i += 1; p.closeSubpath()
            default: i += 1
            }
        }
        return p
    }

