    static let backShapes:  [(part: BodyPart?, sub: String?, path: Path)] = back.map { ($0.0, $0.1, parse($0.2)) }
    static let outlineFrontPath = parse(outlineFront)
    static let outlineBackPath  = parse(outlineBack)

